/**
 * 學生真實提問測試矩陣（Student Query Test Matrix）。
 *
 * ── 為甚麼要有這個檔案 ────────────────────────────────────────────────
 * 2026-11-06 的 17 項回歸項目只覆蓋「已知」缺陷。真實學生會打的句子遠比這些回歸
 * 項目多：低程度學生只打一個專名、高程度學生用「在多大程度上」、有人中英混寫、
 * 有人打錯字、有人把兩個問題擠進一句。這個矩陣把這些寫法固定成可版本控制的資料，
 * 每一條都記錄「預期結果」及「已知失敗模式」，令規則改動時一眼看到影響範圍。
 *
 * ── 誠實聲明（不可省略）────────────────────────────────────────────────
 * 這些案例由工程角度整理，**不是**經歷史科教師逐條審定的 golden answer。因此：
 *   - `reviewStatus: "automated-verified"` 只代表「語言／意圖／深度／硬閘」等
 *     **系統行為**已由自動測試核對；
 *   - 任何涉及「歷史解釋是否合理」「教材是否真的這樣寫」的判斷一律標示為
 *     `"pending-human-review"`，不得自行當作已核准的標準答案。
 *
 * 新增案例的規則：
 *   1. 每一條都要有 `knownFailureMode`（沒有已知失敗模式就寫 `null`，但要說明
 *      為甚麼值得保留在矩陣內）；
 *   2. 期望值只可寫「系統可觀察的行為」（硬閘放行／澄清、回覆深度、短追問辨識），
 *      不可寫「模型應該說某一句話」；
 *   3. 不可為了令測試通過而放寬期望值。
 */
import type { TutorReplyDepth } from "@/lib/types";

/** 提問類別（對應規格第四階段 A–L） */
export type TutorQueryCategory =
  | "A-basic-facts"
  | "B-causes-background"
  | "C-process-development"
  | "D-results-impact"
  | "E-comparison"
  | "F-evaluation-argument"
  | "G-verification-correction"
  | "H-short-follow-up"
  | "I-student-misconceptions"
  | "J-language-variants"
  | "K-ambiguity-multiple-intent"
  | "L-out-of-scope";

export type TutorQueryLanguage = "zh-Hant" | "zh-Hant-yue" | "zh-Hans" | "en" | "mixed";

export type TutorQueryIntent =
  | "factual"
  | "causal"
  | "process"
  | "impact"
  | "comparison"
  | "evaluation"
  | "verification"
  | "follow-up"
  | "off-topic"
  | "exam-technique";

export type TutorQueryLevel = "junior" | "senior" | "unknown";

/**
 * 硬閘期望：
 * - `on-topic`：全新對話單獨提出亦應放行；
 * - `follow-up-only`：只有在同一對話已有歷史上文時才放行（短追問、核對式追問）；
 * - `off-topic`：應被主題硬閘拒絕（固定引導句，不呼叫模型）；
 * - `unclear`：應走澄清（列出 2–4 個歷史方向），不可猜答案。
 */
export type TutorQueryGate = "on-topic" | "follow-up-only" | "off-topic" | "unclear";

export type TutorQuerySeverity = "P0" | "P1" | "P2";

/**
 * 覆核狀態。
 *
 * `automated-verified`：只涉及系統行為（語言、意圖、深度、硬閘），已有自動測試。
 * `pending-human-review`：涉及歷史內容判斷或產品定位，必須由歷史科教師／擁有者決定。
 */
export type TutorQueryReviewStatus = "automated-verified" | "pending-human-review";

export interface TutorQueryCase {
  /** 穩定 ID（不可重用；新增案例用新編號） */
  id: string;
  category: TutorQueryCategory;
  /** 期望所屬課題（`topic-N`／`hs-topic-N`）；`null` = 不約束 */
  topicId: string | null;
  level: TutorQueryLevel;
  /** 學生原句（保留原始標點、錯別字及口語） */
  query: string;
  language: TutorQueryLanguage;
  intent: TutorQueryIntent;
  gate: TutorQueryGate;
  /** 期望回覆深度；`null` = 不約束（例如澄清／離題） */
  depth: TutorReplyDepth | null;
  /** 是否應被辨識為短追問 */
  shortFollowUp: boolean;
  /** 預期檢索結果（人類可讀；供教師覆核，不作自動斷言） */
  expectedRetrieval: string;
  /** 預期答案特徵（人類可讀；供教師覆核，不作自動斷言） */
  expectedAnswerCharacteristics: string;
  /** 已知失敗模式（`null` = 目前未觀察到） */
  knownFailureMode: string | null;
  severity: TutorQuerySeverity;
  reviewStatus: TutorQueryReviewStatus;
}

